def f(gi):
    H=len(gi);W=len(gi[0])
    cnt=Counter(x for row in gi for x in row); bg=cnt.most_common(1)[0][0]
    marks=[(i,j) for i in range(H) for j in range(W) if gi[i][j]!=bg]
    cc=Counter((gi[i][j]) for i,j in marks)
    import math
    cand={}
    for c,n in cc.items():
        s=int(math.sqrt(n)); cand[c]=s if s*s==n and n>1 else -1
    markcol=max(cand,key=cand.get)
    mks={(i,j) for i,j in marks if gi[i][j]==markcol}
    r1=min(i for i,j in mks); r2=max(i for i,j in mks)
    c1=min(j for i,j in mks); c2=max(j for i,j in mks)
    out=[row[:] for row in gi]
    for (pi,pj) in marks:
        if gi[pi][pj]==markcol or gi[pi][pj]==bg: continue
        dr=pi-(r1+r2)/2; dc=pj-(c1+c2)/2
        for sr,sc in [(dr,dc),(-dr,dc),(dr,-dc),(-dr,-dc)]:
            rr=round(r1+(r2-r1)/2+sr); cc_=round(c1+(c2-c1)/2+sc)
            if 0<=rr<H and 0<=cc_<W and gi[rr][cc_]==bg: out[rr][cc_]=gi[pi][pj]
    return out
